<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import type { TopRow } from '../domain/dashboard'
import { formatCreationDate, formatMaterialLabel } from '../domain/formatting'
import MetricValue from './MetricValue.vue'
import SpendCurve from './SpendCurve.vue'
import UiIcon from './UiIcon.vue'
defineProps<{ row:TopRow; date:string }>()
const emit=defineEmits<{close:[]}>()
const dialog=ref<HTMLDialogElement>()
onMounted(()=>dialog.value?.showModal?.())
onBeforeUnmount(()=>dialog.value?.close?.())
</script>
<template><dialog ref="dialog" class="material-drawer" aria-labelledby="material-drawer-title" @cancel.prevent="emit('close')" @click="event=>{if(event.target===dialog)emit('close')}"><div class="drawer-content"><header><p class="overline">MATERIAL DETAIL <span>素材详情</span></p><button class="icon-button" aria-label="关闭素材详情" @click="emit('close')"><UiIcon name="close"/></button></header><span class="drawer-rank">RANK / {{ String(row.rank).padStart(2,'0') }}</span><h2 id="material-drawer-title">{{ row.materialName??'名称未知' }}</h2><p class="drawer-id">{{ formatMaterialLabel(row.materialId,row.materialName) }}</p><div class="drawer-context"><span>统计日 <b>{{ date }}</b></span><span>首次投放时间 <b>{{ formatCreationDate(row.creationDate) }}</b></span></div><div class="drawer-primary"><article><span>当天消耗 · 元</span><strong><MetricValue :result="row.dailySpend.find(d=>d.date===date)?.spend"/></strong></article><article><span>当天 ROI</span><strong><MetricValue :result="row.dayRoi"/></strong></article></div><section class="drawer-trend"><h3>近 7 天消耗走势</h3><SpendCurve :days="row.dailySpend" expanded/><div class="drawer-range"><span>近 7 天消耗 <MetricValue :result="row.windowSpend"/></span><span>近 7 天 ROI <MetricValue :result="row.windowRoi"/></span></div></section><section class="drawer-recent"><h3>近 3 天表现</h3><div class="drawer-metrics"><article><span>消耗</span><strong><MetricValue :result="row.recent3Spend"/></strong></article><article><span>ROI</span><strong><MetricValue :result="row.recent3Roi"/></strong></article><article><span>CPM</span><strong><MetricValue :result="row.recent3Cpm"/></strong></article><article><span>CPC</span><strong><MetricValue :result="row.recent3Cpc"/></strong></article><article><span>展现次数</span><strong><MetricValue :result="row.recent3Impressions" format="integer"/></strong></article><article><span>点击次数</span><strong><MetricValue :result="row.recent3Clicks" format="integer"/></strong></article><article><span>点击率</span><strong><MetricValue :result="row.recent3Ctr" format="percent"/></strong></article><article><span>转化率</span><strong><MetricValue :result="row.recent3Cvr" format="percent"/></strong></article></div></section><section class="drawer-lifetime"><h3>累计表现 <small>已有数据</small></h3><div class="drawer-primary"><article><span>累计消耗 · 元</span><strong><MetricValue :result="row.lifetimeSpend"/></strong></article><article><span>累计 ROI</span><strong><MetricValue :result="row.lifetimeRoi"/></strong></article></div></section><p class="module-note">未知与缺失保留原状态；趋势中的断线代表缺失日期。</p></div></dialog></template>
